// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount == 10);
        vm.deal(address(this), 10);
        uint balBefore = address(c).balance;
        uint potBefore = c.pot();
        (bool success, ) = address(c).call{value: 10}(abi.encodeWithSignature("play()"));
        require(success, "call failed");
        uint potAfter = c.pot();
        bool random = (uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % 2) == 0;
        if (random) {
            assertTrue(potAfter == 0);
        } else {
            assertTrue(potAfter == 10);
        }
    }
}

